// Round-trip test: Rust serializes a minimal Character → JSON → Zod validates
// it (§3.6, §16). This is the cross-language schema guarantee in one test:
// if the Rust types and the generated Zod drift, this fails.
//
// Also exercises canonicalPath() — a valid path compiles, and the runtime
// value is the path string itself (§6.3).

import { describe, it, expect } from "vitest";
import { characterSchema } from "@nexus-ttrpg/schema-zod";
import { canonicalPath } from "./index.js";

// Generated by `cargo run -p schema-core --example dump_json` — a minimal
// Character serialized from the Rust `minimal_build()` fixture (§16).
const minimalCharacter = {
  build: {
    abilityScores: {
      str: {
        boosts: [{ source: "ancestry" }],
        flaws: [],
        itemBonus: 0,
      },
    },
    actions: [],
    ancestry: {
      displayName: null,
      reference: {
        foundryUuid: null,
        roll20Id: null,
        slug: "human",
        source: null,
      },
    },
    background: {
      displayName: null,
      reference: {
        foundryUuid: null,
        roll20Id: null,
        slug: "scholar",
        source: null,
      },
    },
    class: {
      hpPerLevel: 10,
      keyAbility: "str",
      reference: {
        foundryUuid: null,
        roll20Id: null,
        slug: "fighter",
        source: null,
      },
    },
    classFeatures: [],
    companions: [],
    currencies: {
      cp: null,
      credits: null,
      gp: null,
      pp: null,
      sp: null,
      upb: null,
    },
    drones: [],
    equipment: { armor: [], inventory: [], weapons: [] },
    explorationActivities: [],
    familiars: [],
    feats: [],
    heritage: {
      displayName: null,
      reference: {
        foundryUuid: null,
        roll20Id: null,
        slug: "half-elf",
        source: null,
      },
    },
    identity: {
      name: "Test Character",
      playerName: null,
      pronouns: null,
    },
    level: 1,
    notes: [],
    proficiencies: {},
    reactions: [],
    skills: {},
    spellcasting: { entries: [] },
    vehicles: [],
  },
  extensions: {},
  meta: {
    contentHash: "0".repeat(64),
    createdAt: "2025-01-01T00:00:00Z",
    displayName: "Test Character",
    id: "01HXYZ1234567890ABCDEFGHJK",
    ownerId: "01HXYZ1234567890ABCDEFGHJK",
    schemaVersion: "0.1.0",
    system: "pf2e",
    updatedAt: "2025-01-01T00:00:00Z",
  },
  session: {
    conditions: [],
    encounterEffects: [],
    focusPoints: { current: 0, max: 0 },
    heroPoints: 0,
    hitPoints: { current: 10, max: 10, temporary: 0 },
    lastObservedAt: "2025-01-01T00:00:00Z",
    platform: "foundry",
    spellSlots: {},
    temporaryModifiers: [],
  },
};

describe("codegen round-trip (§3.6)", () => {
  it("Zod schema validates a minimal character serialized from Rust", () => {
    const result = characterSchema.safeParse(minimalCharacter);
    expect(result.success).toBe(true);
  });

  it("Zod schema rejects an invalid character (bad enum value)", () => {
    const bad = {
      ...minimalCharacter,
      build: {
        ...minimalCharacter.build,
        class: {
          ...minimalCharacter.build.class,
          keyAbility: "strength", // not a valid AbilityScoreKey
        },
      },
    };
    const result = characterSchema.safeParse(bad);
    expect(result.success).toBe(false);
  });

  it("Zod schema rejects an invalid character (missing required field)", () => {
    const bad = {
      ...minimalCharacter,
      build: {
        ...minimalCharacter.build,
        identity: { playerName: null, pronouns: null }, // missing "name"
      },
    };
    const result = characterSchema.safeParse(bad);
    expect(result.success).toBe(false);
  });
});

describe("canonicalPath() (§6.3)", () => {
  it("accepts valid paths and returns them as-is", () => {
    expect(canonicalPath("build.identity.name")).toBe("build.identity.name");
    expect(canonicalPath("build.level")).toBe("build.level");
    expect(canonicalPath("build.abilityScores.str")).toBe(
      "build.abilityScores.str",
    );
    expect(canonicalPath("build.feats")).toBe("build.feats");
    expect(canonicalPath("build.class.hpPerLevel")).toBe(
      "build.class.hpPerLevel",
    );
    expect(canonicalPath("meta.id")).toBe("meta.id");
    expect(canonicalPath("session.platform")).toBe("session.platform");
  });

  it("canonicalPath paths are usable as record keys", () => {
    const map = {
      [canonicalPath("build.identity.name")]: "character_name",
      [canonicalPath("build.level")]: "level",
    } as const;
    expect(map["build.identity.name"]).toBe("character_name");
    expect(map["build.level"]).toBe("level");
  });
});
